const PART = /(\d+(?:\.\d+)?)(m|ms|s|h|d)/y;
const UNITS = { ms: 1, s: 1000, m: 60000, h: 3600000, d: 86400000 };
function parseDuration(input) {
  if (typeof input === 'number') {
    if (!Number.isFinite(input) || input < 0) throw new RangeError('invalid duration: ' + input);
    return input;
  }
  const text = String(input).trim();
  let total = 0;
  PART.lastIndex = 0;
  while (PART.lastIndex < text.length) {
    const m = PART.exec(text);
    if (!m) throw new RangeError('invalid duration: ' + input);
    total += Number(m[1]) * UNITS[m[2]];
  }
  if (text === '') throw new RangeError('invalid duration: ' + input);
  return total;
}
for (const s of ['250ms','1s','1.5s','1h30m','2d','5m',' 90s ','10','5x','1h 30m','m5','']) {
  try { console.log(JSON.stringify(s), '->', parseDuration(s)); } catch (e) { console.log(JSON.stringify(s), '-> throws', e.message); }
}
"
